	private static Class<?> requiredClass(String name) {
		try {
			return Class.forName(name);
		} catch (ClassNotFoundException exception) {
			return fail("Missing theorem-safe packed session type " + name, exception);
		}
	}

	private static Method requiredMethod(Class<?> owner, String name, Class<?>... parameterTypes) {
		try {
			return owner.getMethod(name, parameterTypes);
		} catch (NoSuchMethodException exception) {
			return fail("Missing packed Frontier contract " + owner.getSimpleName() + "." + name, exception);
		}
	}

	private static Method requiredDeclaredMethod(Class<?> owner, String name, Class<?>... parameterTypes) {
		try {
			Method method = owner.getDeclaredMethod(name, parameterTypes);
			method.setAccessible(true);
			return method;
		} catch (NoSuchMethodException exception) {
			return fail("Missing packed Frontier hot-path contract " + owner.getSimpleName() + "." + name,
					exception);
		}
	}

	private static Field requiredField(Class<?> owner, String name) {
		try {
			Field field = owner.getDeclaredField(name);
			field.setAccessible(true);
			return field;
		} catch (NoSuchFieldException exception) {
			return fail("Missing packed Frontier field " + owner.getSimpleName() + "." + name, exception);
		}
	}

	private static void assertPrimitiveStateColumn(Class<?> owner) {
		Field field = Arrays.stream(owner.getDeclaredFields())
				.filter(candidate -> candidate.getName().equals("evidenceStateId"))
				.findFirst()
				.orElseGet(() -> fail(owner.getSimpleName() + " must retain an aligned evidenceStateId column"));
		assertEquals(int.class, field.getType(), "Packed state references must remain allocation-free primitive IDs");
	}

	private static void assertNoQueryLocalFrontierFields(Class<?> owner) {
		for (Field field : owner.getDeclaredFields()) {
			String normalizedName = field.getName().replace("_", "").toLowerCase();
			String typeName = field.getType().getSimpleName();
			assertFalse(normalizedName.contains("evidencestate"),
					() -> owner.getSimpleName() + "." + field.getName() + " leaks a query-local evidence ID");
			assertFalse(typeName.equals("PackedCostSession")
					|| typeName.equals("EvidenceStateRef")
					|| typeName.equals("FrontierStateArena"),
					() -> owner.getSimpleName() + "." + field.getName() + " leaks " + typeName);
		}
	}
